        if (*line != ':')
                return line;

        *nick = ++line; p = NULL;
        while (*line != '\0' && *line != ' ') {
                if (*line == '!' || *line == '@') {
                        p = line;
                        if (*line == '!')
                                break;
                }
                line++;
        }

        if (p != NULL) {
                line = p;
                *line++ = '\0';
                *address = line;
                while (*line != '\0' && *line != ' ')
                        line++;
        }

        if (*line == ' ') {
                *line++ = '\0';
                while (*line == ' ') line++;
        }

        return line;
